package diffcheck

import (
	"path"
	"regexp"
	"strings"
)

// Generated answers whether a path is marked linguist-generated by the
// repo's .gitattributes files. The zero value matches nothing.
type Generated struct {
	rules []generatedRule
}

type generatedRule struct {
	dir     string // directory holding the .gitattributes, "" for the root
	pattern string
}

// AddGitattributes registers a .gitattributes file located in dir (repo
// relative, "" for root). Only `linguist-generated` / `linguist-generated=true`
// lines are honoured; negations and macros are ignored.
func (g *Generated) AddGitattributes(dir, content string) {
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Fields(line)
		for _, attr := range fields[1:] {
			if attr == "linguist-generated" || attr == "linguist-generated=true" {
				g.rules = append(g.rules, generatedRule{dir: strings.Trim(dir, "/"), pattern: fields[0]})
			}
		}
	}
}

func (g *Generated) Matches(p string) bool {
	if g == nil {
		return false
	}
	for _, r := range g.rules {
		rel := p
		if r.dir != "" {
			if !strings.HasPrefix(p, r.dir+"/") {
				continue
			}
			rel = strings.TrimPrefix(p, r.dir+"/")
		}
		pat := strings.TrimPrefix(r.pattern, "/")
		target := rel
		if !strings.Contains(pat, "/") {
			target = path.Base(rel)
		}
		if globMatch(pat, target) {
			return true
		}
	}
	return false
}

// globMatch is path.Match plus git's `**` (any number of directories).
func globMatch(pat, target string) bool {
	if !strings.Contains(pat, "**") {
		ok, _ := path.Match(pat, target)
		return ok
	}
	var b strings.Builder
	b.WriteString("^")
	for i := 0; i < len(pat); i++ {
		switch {
		case strings.HasPrefix(pat[i:], "**/"):
			b.WriteString("(?:.*/)?")
			i += 2
		case strings.HasPrefix(pat[i:], "**"):
			b.WriteString(".*")
			i++
		case pat[i] == '*':
			b.WriteString("[^/]*")
		case pat[i] == '?':
			b.WriteString("[^/]")
		default:
			b.WriteString(regexp.QuoteMeta(pat[i : i+1]))
		}
	}
	b.WriteString("$")
	re, err := regexp.Compile(b.String())
	return err == nil && re.MatchString(target)
}
